import time
import six
from abc import ABCMeta
from taf.ue.plugin.mtk.exceptions import (ManyTriesStillFail, CriteriaMessageMismatched,
                                          CriteriaMessageHappenedOutOfOrder)


@six.add_metaclass(ABCMeta)
class MessageVerifier(object):
    def verify(self):
        pass

    @staticmethod
    def check_in_msg_string(criteria_string_list, source_msg):
        msg_len = len(source_msg)

        last_index = -1
        last_criteria = ""
        for criteria in criteria_string_list:
            index = source_msg.find(criteria, 0, msg_len)
            if index == -1:
                raise CriteriaMessageMismatched(
                    "criteria message: {}, in source message {}".format(criteria, source_msg))
            if index <= last_index:
                raise CriteriaMessageHappenedOutOfOrder("current criteria message: {} happened before "
                                                        "last criteria message: {}, "
                                                        "in source message {}".
                                                        format(criteria, last_criteria, source_msg))
            last_index = index
            last_criteria = criteria

    @staticmethod
    def check_in_msg_string_list(criteria_string_list, source_msg_list):

        last_index = -1
        last_criteria = ""
        for criteria in criteria_string_list:
            for index in range(0, len(source_msg_list)):
                msg = source_msg_list[index]
                if criteria not in msg:
                    continue
                if index <= last_index:
                    raise CriteriaMessageHappenedOutOfOrder("current criteria message: {} happened before "
                                                            "last criteria message: {}, "
                                                            "in source message {}".
                                                            format(criteria, last_criteria, source_msg_list))
                last_index = index
                last_criteria = criteria
                break
            else:
                raise CriteriaMessageMismatched(
                    "criteria message: {}, in source message {}".format(criteria, source_msg_list))


class ManyTriesTrueFalseVerifier(object):
    def __init__(self, executor, one_wait_timeout, tries, *args, **kwargs):
        self._executor = executor
        self._one_wait_timeout = one_wait_timeout or 10
        self._tries = tries or 3
        self._args = args
        self._kwargs = kwargs

    def verify(self):
        while self._tries:
            if hasattr(self._executor, '__call__'):
                if self._executor(*self._args, **self._kwargs):
                    return
                else:
                    time.sleep(self._one_wait_timeout)
                    self._tries -= 1
            elif self._executor.execute(*self._kwargs, **self._kwargs):
                return
            else:
                time.sleep(self._one_wait_timeout)
                self._tries -= 1
        raise ManyTriesStillFail("{} tries failure reach".format(self._tries))
